use clap::{Parser,Subcommand};use sandbox_server_runner::{config::RunnerConfig,pairing::pair};use std::path::PathBuf;
#[derive(Parser)]#[command(name="sandbox-runner",version)]struct Cli{#[arg(long,default_value="/etc/sandbox-runner/config.toml")]config:PathBuf,#[command(subcommand)]command:Command}
#[derive(Subcommand)]enum Command{Pair{#[arg(long,env="SANDBOX_PAIRING_TOKEN",hide_env_values=true)]token:String},Validate,Run}
#[tokio::main]async fn main(){if let Err(error)=run().await{eprintln!("{error}");std::process::exit(1)}}
async fn run()->Result<(),String>{let cli=Cli::parse();let config=RunnerConfig::load(&cli.config).map_err(|error|error.to_string())?;match cli.command{Command::Validate=>println!("configuration valid"),Command::Pair{token}=>{std::fs::create_dir_all(&config.data_directory).map_err(|error|error.to_string())?;let(identity,fingerprint)=pair(&config,&token).await?;identity.save(&config.data_directory.join("identity.json"))?;println!("Pairing request accepted. Confirm fingerprint: {fingerprint}");},Command::Run=>{if !config.data_directory.join("identity.json").exists(){return Err("Runner is not paired.".into());}println!("runner starting in {} with concurrency {}",config.environment,config.concurrency);tokio::signal::ctrl_c().await.map_err(|error|error.to_string())?;}}Ok(())}
